# --- 프록시 더미를 본다 ---

@GetMapping("/advisors")
@ResponseBody
public String advisors() {
    Advised advised = (Advised) orderService;
    for (Advisor a : advised.getAdvisors()) {
        System.out.println(">>> " + a.getClass().getSimpleName()
                + "  " + (a instanceof Ordered o ? o.getOrder() : "-"));
    }
    return "ok";
}

